ALTER TABLE public.vehicle_bookings ADD COLUMN sale_kind text NOT NULL DEFAULT 'online' CHECK (sale_kind IN ('online','showroom')), ADD COLUMN discount_amount numeric NOT NULL DEFAULT 0 CHECK (discount_amount >= 0), ADD COLUMN discount_reason text, ADD COLUMN created_by_name text, ADD COLUMN blocked_reason text;
ALTER TABLE public.vehicle_registrations ADD COLUMN battery_number text;
CREATE TABLE public.booking_receipts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.vehicle_bookings(id) ON DELETE RESTRICT, amount numeric NOT NULL CHECK(amount > 0), payer_type text NOT NULL CHECK(payer_type IN ('customer','lender','exchange_setoff')), method text NOT NULL, reference text, note text, received_on date NOT NULL DEFAULT CURRENT_DATE, recorded_by uuid NOT NULL, recorded_by_name text NOT NULL, voided_at timestamptz, voided_by uuid, void_reason text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.booking_receipts TO authenticated;
GRANT ALL ON public.booking_receipts TO service_role;
ALTER TABLE public.booking_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read booking receipts" ON public.booking_receipts FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE INDEX booking_receipts_booking_created_idx ON public.booking_receipts(booking_id,created_at);
CREATE FUNCTION public.protect_booking_receipt() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Receipts cannot be deleted; void them instead'; END IF; IF OLD.voided_at IS NOT NULL OR NEW.id IS DISTINCT FROM OLD.id OR NEW.booking_id IS DISTINCT FROM OLD.booking_id OR NEW.amount IS DISTINCT FROM OLD.amount OR NEW.payer_type IS DISTINCT FROM OLD.payer_type OR NEW.method IS DISTINCT FROM OLD.method OR NEW.reference IS DISTINCT FROM OLD.reference OR NEW.note IS DISTINCT FROM OLD.note OR NEW.received_on IS DISTINCT FROM OLD.received_on OR NEW.recorded_by IS DISTINCT FROM OLD.recorded_by OR NEW.recorded_by_name IS DISTINCT FROM OLD.recorded_by_name OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.voided_at IS NULL OR NEW.voided_by IS NULL OR length(trim(COALESCE(NEW.void_reason,'')))<3 THEN RAISE EXCEPTION 'Receipt corrections must be a reasoned void'; END IF; RETURN NEW; END $$;
CREATE TRIGGER booking_receipt_history BEFORE UPDATE OR DELETE ON public.booking_receipts FOR EACH ROW EXECUTE FUNCTION public.protect_booking_receipt();
CREATE FUNCTION public.booking_outstanding(p_booking_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT GREATEST(0,b.on_road_total-CASE WHEN b.payment_status='paid' THEN b.token_amount ELSE 0 END-COALESCE((SELECT SUM(r.amount) FROM public.booking_receipts r WHERE r.booking_id=b.id AND r.voided_at IS NULL),0)) FROM public.vehicle_bookings b WHERE b.id=p_booking_id $$;
CREATE FUNCTION public.showroom_lines_total(p_lines jsonb) RETURNS numeric LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v_line jsonb; v_total numeric:=0; BEGIN IF jsonb_typeof(p_lines) IS DISTINCT FROM 'array' OR jsonb_array_length(p_lines)=0 OR jsonb_array_length(p_lines)>50 THEN RAISE EXCEPTION 'Add between 1 and 50 price lines'; END IF; FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP IF length(trim(COALESCE(v_line->>'label','')))=0 OR (v_line->>'kind') NOT IN ('vehicle','rto','insurance','accessory','subsidy','discount','finance_fee') OR v_line->>'kind' IS NULL OR jsonb_typeof(v_line->'amount') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Invalid price line'; END IF; IF (v_line->>'amount')::numeric < 0 AND (v_line->>'kind') NOT IN ('subsidy','discount') THEN RAISE EXCEPTION 'Only subsidy and discount lines may be negative'; END IF; IF (v_line->>'amount')::numeric > 0 AND (v_line->>'kind') IN ('subsidy','discount') THEN RAISE EXCEPTION 'Subsidy and discount lines must be zero or negative'; END IF; v_total:=v_total+(v_line->>'amount')::numeric; END LOOP; RETURN round(v_total,2); END $$;
CREATE FUNCTION public.create_showroom_booking(p_product_id uuid,p_customer jsonb,p_lines jsonb,p_discount numeric,p_discount_reason text,p_expected_delivery date,p_actor_id uuid,p_actor_name text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; v_human text; v_total numeric; BEGIN IF NOT public.is_staff(p_actor_id) OR public.staff_role(p_actor_id)::text='online_sales' THEN RAISE EXCEPTION 'Operations access required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.products WHERE id=p_product_id AND product_kind='vehicle' AND status='visible') THEN RAISE EXCEPTION 'This model is unavailable'; END IF; IF length(trim(COALESCE(p_customer->>'name','')))=0 OR COALESCE(p_customer->>'phone','') !~ '^[0-9]{10}$' THEN RAISE EXCEPTION 'Customer name and 10-digit phone required'; END IF; IF p_discount IS NULL OR p_discount<0 OR (p_discount>0 AND (public.staff_role(p_actor_id)::text NOT IN ('manager','owner','super_admin') OR length(trim(COALESCE(p_discount_reason,'')))<3)) THEN RAISE EXCEPTION 'Manager approval and reason required for discount'; END IF; v_total:=public.showroom_lines_total(p_lines)-p_discount; IF v_total<=0 THEN RAISE EXCEPTION 'Agreed total must be positive'; END IF; v_human:='SCB-'||to_char(now(),'YYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)); INSERT INTO public.vehicle_bookings(human_id,product_id,profile_id,customer_name,phone,alternate_phone,address,sale_kind,price_breakdown,on_road_total,token_amount,balance_due,discount_amount,discount_reason,created_by_name,expected_delivery) VALUES(v_human,p_product_id,NULL,p_customer->>'name',p_customer->>'phone',NULLIF(p_customer->>'alternatePhone',''),NULLIF(p_customer->>'address',''),'showroom',p_lines,v_total,0,v_total,p_discount,NULLIF(p_discount_reason,''),p_actor_name,p_expected_delivery) RETURNING id INTO v_id; INSERT INTO public.booking_events(booking_id,status,note,created_by) VALUES(v_id,'booked','Showroom sale created by '||p_actor_name,p_actor_name); RETURN jsonb_build_object('id',v_id,'humanId',v_human); END $$;
CREATE FUNCTION public.record_booking_receipt(p_booking_id uuid,p_amount numeric,p_payer_type text,p_method text,p_reference text,p_received_on date,p_note text,p_actor_id uuid,p_actor_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.vehicle_bookings; v_id uuid; BEGIN IF NOT public.is_staff(p_actor_id) OR public.staff_role(p_actor_id)::text='online_sales' THEN RAISE EXCEPTION 'Operations access required'; END IF; SELECT * INTO b FROM public.vehicle_bookings WHERE id=p_booking_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown booking'; END IF; IF b.status='cancelled' THEN RAISE EXCEPTION 'Cancelled bookings cannot receive payments'; END IF; IF p_amount IS NULL OR p_amount<=0 OR p_amount>public.booking_outstanding(b.id) THEN RAISE EXCEPTION 'Receipt amount exceeds outstanding or is invalid'; END IF; IF length(trim(COALESCE(p_method,'')))=0 THEN RAISE EXCEPTION 'Payment method required'; END IF; INSERT INTO public.booking_receipts(booking_id,amount,payer_type,method,reference,received_on,note,recorded_by,recorded_by_name) VALUES(b.id,p_amount,p_payer_type,p_method,NULLIF(p_reference,''),COALESCE(p_received_on,CURRENT_DATE),NULLIF(p_note,''),p_actor_id,p_actor_name) RETURNING id INTO v_id; UPDATE public.vehicle_bookings SET balance_due=public.booking_outstanding(b.id),updated_at=now() WHERE id=b.id; INSERT INTO public.booking_events(booking_id,status,note,created_by) VALUES(b.id,b.status,'Receipt recorded: ₹'||p_amount,p_actor_name); RETURN v_id; END $$;
CREATE FUNCTION public.void_booking_receipt(p_receipt_id uuid,p_reason text,p_actor_id uuid,p_actor_name text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_booking uuid; b public.vehicle_bookings; r public.booking_receipts; BEGIN IF public.staff_role(p_actor_id)::text NOT IN ('manager','owner','super_admin') OR public.staff_role(p_actor_id) IS NULL THEN RAISE EXCEPTION 'Manager access required'; END IF; IF length(trim(COALESCE(p_reason,'')))<3 THEN RAISE EXCEPTION 'Add a void reason'; END IF; SELECT booking_id INTO v_booking FROM public.booking_receipts WHERE id=p_receipt_id; SELECT * INTO b FROM public.vehicle_bookings WHERE id=v_booking FOR UPDATE; SELECT * INTO r FROM public.booking_receipts WHERE id=p_receipt_id FOR UPDATE; IF NOT FOUND OR r.voided_at IS NOT NULL THEN RAISE EXCEPTION 'Receipt missing or already voided'; END IF; UPDATE public.booking_receipts SET voided_at=now(),voided_by=p_actor_id,void_reason=p_reason WHERE id=r.id; UPDATE public.vehicle_bookings SET balance_due=public.booking_outstanding(b.id),updated_at=now() WHERE id=b.id; INSERT INTO public.booking_events(booking_id,status,note,created_by) VALUES(b.id,b.status,'Receipt voided: ₹'||r.amount||' — '||p_reason,p_actor_name); RETURN true; END $$;
CREATE FUNCTION public.adjust_booking_agreed_price(p_booking_id uuid,p_lines jsonb,p_discount numeric,p_discount_reason text,p_actor_id uuid,p_actor_name text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.vehicle_bookings; v_total numeric; v_collected numeric; BEGIN IF public.staff_role(p_actor_id)::text NOT IN ('manager','owner','super_admin') OR public.staff_role(p_actor_id) IS NULL THEN RAISE EXCEPTION 'Manager access required'; END IF; SELECT * INTO b FROM public.vehicle_bookings WHERE id=p_booking_id FOR UPDATE; IF NOT FOUND OR b.status IN ('cancelled','delivered') THEN RAISE EXCEPTION 'Only open bookings can be repriced'; END IF; IF p_discount IS NULL OR p_discount<0 OR (p_discount>0 AND length(trim(COALESCE(p_discount_reason,'')))<3) THEN RAISE EXCEPTION 'Add a discount reason'; END IF; v_total:=public.showroom_lines_total(p_lines)-p_discount; v_collected:=CASE WHEN b.payment_status='paid' THEN b.token_amount ELSE 0 END+COALESCE((SELECT sum(amount) FROM public.booking_receipts WHERE booking_id=b.id AND voided_at IS NULL),0); IF v_total<=0 OR v_total<v_collected OR (b.sale_kind='online' AND v_total<b.token_amount) THEN RAISE EXCEPTION 'Agreed price cannot be below the token or payments received'; END IF; INSERT INTO public.audit_log(actor,action,entity,entity_id,diff) VALUES(p_actor_name,'booking.agreed_price_snapshot','vehicle_bookings',b.id::text,jsonb_build_object('beforeLines',b.price_breakdown,'beforeTotal',b.on_road_total,'afterLines',p_lines,'afterTotal',v_total)); UPDATE public.vehicle_bookings SET price_breakdown=p_lines,on_road_total=v_total,discount_amount=p_discount,discount_reason=p_discount_reason,balance_due=GREATEST(0,v_total-v_collected),updated_at=now() WHERE id=b.id; INSERT INTO public.booking_events(booking_id,status,note,created_by) VALUES(b.id,b.status,'Agreed price adjusted by '||p_actor_name,p_actor_name); RETURN true; END $$;
CREATE FUNCTION public.guard_showroom_delivery() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.sale_kind='showroom' AND NEW.status='delivered' AND OLD.status IS DISTINCT FROM NEW.status AND public.booking_outstanding(OLD.id)>0 AND COALESCE(current_setting('app.showroom_delivery_override',true),'')<>OLD.id::text THEN RAISE EXCEPTION 'Outstanding showroom balance — an Owner must approve delivery'; END IF; RETURN NEW; END $$;
CREATE TRIGGER showroom_delivery_gate BEFORE UPDATE OF status ON public.vehicle_bookings FOR EACH ROW EXECUTE FUNCTION public.guard_showroom_delivery();
CREATE FUNCTION public.deliver_booking_with_balance(p_booking_id uuid,p_chassis text,p_motor text,p_registration text,p_battery text,p_warranty date,p_delivered date,p_override_reason text,p_actor_id uuid,p_actor_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.vehicle_bookings; v_balance numeric; v_reg uuid; BEGIN IF NOT public.is_staff(p_actor_id) OR public.staff_role(p_actor_id)::text='online_sales' THEN RAISE EXCEPTION 'Operations access required'; END IF; SELECT * INTO b FROM public.vehicle_bookings WHERE id=p_booking_id FOR UPDATE; IF NOT FOUND OR b.status='cancelled' THEN RAISE EXCEPTION 'Unknown or cancelled booking'; END IF; IF length(trim(COALESCE(p_chassis,'')))=0 OR length(trim(COALESCE(p_motor,'')))=0 THEN RAISE EXCEPTION 'Chassis and motor numbers required'; END IF; v_balance:=public.booking_outstanding(b.id); IF b.sale_kind='showroom' AND v_balance>0 THEN IF public.staff_role(p_actor_id)::text NOT IN ('owner','super_admin') OR public.staff_role(p_actor_id) IS NULL OR length(trim(COALESCE(p_override_reason,'')))=0 THEN RAISE EXCEPTION 'Outstanding balance of ₹% — an Owner must approve delivery.',v_balance; END IF; PERFORM set_config('app.showroom_delivery_override',b.id::text,true); END IF; IF v_balance>0 THEN INSERT INTO public.booking_events(booking_id,status,note,created_by) VALUES(b.id,b.status,'Handover with outstanding ₹'||v_balance||CASE WHEN b.sale_kind='showroom' THEN ' — Owner override: '||p_override_reason ELSE ' — online balance uncollected' END,p_actor_name); INSERT INTO public.audit_log(actor,action,entity,entity_id,diff) VALUES(p_actor_name,'booking.handover_outstanding','vehicle_bookings',b.id::text,jsonb_build_object('outstanding',v_balance,'reason',p_override_reason,'saleKind',b.sale_kind)); END IF; INSERT INTO public.vehicle_registrations(booking_id,product_id,profile_id,owner_name,phone,chassis_number,motor_number,registration_number,battery_number,warranty_start,delivered_on) VALUES(b.id,b.product_id,b.profile_id,b.customer_name,b.phone,p_chassis,p_motor,NULLIF(p_registration,''),NULLIF(trim(p_battery),''),COALESCE(p_warranty,CURRENT_DATE),COALESCE(p_delivered,CURRENT_DATE)) ON CONFLICT(booking_id) DO UPDATE SET chassis_number=EXCLUDED.chassis_number,motor_number=EXCLUDED.motor_number,registration_number=EXCLUDED.registration_number,battery_number=COALESCE(EXCLUDED.battery_number,vehicle_registrations.battery_number),warranty_start=EXCLUDED.warranty_start,delivered_on=EXCLUDED.delivered_on,updated_at=now() RETURNING id INTO v_reg; PERFORM public.build_service_schedule(v_reg); UPDATE public.vehicle_bookings SET status='delivered',updated_at=now() WHERE id=b.id; INSERT INTO public.booking_events(booking_id,status,note,created_by) VALUES(b.id,'delivered','Vehicle handed over',p_actor_name); RETURN v_reg; END $$;
REVOKE ALL ON FUNCTION public.protect_booking_receipt(),public.booking_outstanding(uuid),public.showroom_lines_total(jsonb),public.create_showroom_booking(uuid,jsonb,jsonb,numeric,text,date,uuid,text),public.record_booking_receipt(uuid,numeric,text,text,text,date,text,uuid,text),public.void_booking_receipt(uuid,text,uuid,text),public.adjust_booking_agreed_price(uuid,jsonb,numeric,text,uuid,text),public.guard_showroom_delivery(),public.deliver_booking_with_balance(uuid,text,text,text,text,date,date,text,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.protect_booking_receipt(),public.booking_outstanding(uuid),public.showroom_lines_total(jsonb),public.create_showroom_booking(uuid,jsonb,jsonb,numeric,text,date,uuid,text),public.record_booking_receipt(uuid,numeric,text,text,text,date,text,uuid,text),public.void_booking_receipt(uuid,text,uuid,text),public.adjust_booking_agreed_price(uuid,jsonb,numeric,text,uuid,text),public.guard_showroom_delivery(),public.deliver_booking_with_balance(uuid,text,text,text,text,date,date,text,uuid,text) TO service_role;